<template>
    <div class="flex">
        <button
            class="px-1.5 hover:text-primary-700 transition"
            :class="value.description || value.value ? 'text-primary-700' : 'text-gray-500'"
            :data-tooltip="$t('button_tooltip')"
            data-tooltip-location="bottom"
            @click.prevent="doOpen"
        >
            <EcomIcon :source="icons.ChatBotIcon" :size="'w-4'" class="flex"></EcomIcon>
        </button>
        <!-- <Teleport to="body">
            <BackDrop v-if="open" @click.prevent="doClose"></BackDrop>
        </Teleport> -->
        <div
            v-if="open"
            class="shadow-md border my-1 px-3 py-3 top-full absolute left-0 right-0 bg-white rounded transition z-50 w-full">
            <div class="flex flex-col gap-3">
                <div class="flex flex-col gap-1">
                    <div class="flex justify-between gap-2">
                        <label class="block text-gray-700 text-xs">{{ $t('description_field_label') }}</label>
                        <div class="flex gap-1">
                            <Popover
                                :open="popoverOpen"
                                :triggerClass="'flex items-center justify-center'"
                                :contentClass="'bg-white rounded-lg shadow-lg ring-1 ring-gray-200 w-36 flex bg-white rounded-lg shadow-lg translate-x-4'"
                                :preferred-alignment="'end'"
                                @close="popoverOpen = false">
                                <template #trigger>
                                    <button
                                        class="text-gray-500 hover:text-primary-700"
                                        data-tooltip="Predefined role"
                                        @click.prevent="popoverOpen = true">
                                        <EcomIcon
                                            :size="'w-4'"
                                            class="h-4 flex items-center justify-center" :source="icons.SelectIcon" />
                                    </button>
                                </template>
                                <template #default="{ onClose }: { onClose: () => void }">
                                    <div class="w-full flex flex-col gap-1 p-2 max-h-[33vh] overflow-auto" ref="popoverContent">
                                        <button v-for="role in predefinedRoles" @click.prevent="setDescription(role); onClose()"
                                            class="block w-full rounded-md px-1 py-0.5 text-xs text-left text-gray-700 hover:bg-gray-150 transition">
                                            {{ role }}
                                        </button>
                                    </div>
                                </template>
                            </Popover>
                            <button
                                class="text-gray-500 hover:text-primary-700 transition"
                                :data-tooltip="'Clear'"
                                data-tooltip-location="bottom"
                                @click.prevent="doClear('description')"
                            >
                                <EcomIcon :source="icons.ecEraser" :size="'w-4'" class="flex"></EcomIcon>
                            </button>
                        </div>
                    </div>
                    <textarea
                        :id="id + '-description'"
                        v-model="value.description"
                        type="text"
                        class="w-full h-11 text-xs px-2 py-1 border border-gray-300 rounded shadow-sm rtransition focus:border-gray-300"
                        tabindex="3"
                    ></textarea>
                </div>
                <div class="flex flex-col gap-1">
                    <div class="flex justify-between gap-2">
                        <label class="block text-gray-700 text-xs">{{ $t('value_field_label') }}</label>
                        <span class="flex gap-1">
                            <button
                                class="text-gray-500 hover:text-primary-700 transition"
                                :data-tooltip="'Add existing content'"
                                data-tooltip-location="bottom"
                                @click.prevent="doAddValue(); doFocus('value');"
                            >
                                <EcomIcon :source="icons.ecPlus" :size="'w-4'" class="flex"></EcomIcon>
                            </button>
                            <button
                                class="text-gray-500 hover:text-primary-700 transition"
                                :data-tooltip="'Clear'"
                                data-tooltip-location="bottom"
                                @click.prevent="doClear('value')"
                            >
                                <EcomIcon :source="icons.ecEraser" :size="'w-4'" class="flex"></EcomIcon>
                            </button>
                        </span>
                    </div>
                    <textarea
                        :id="id + '-value'"
                        v-model="value.value"
                        type="text"
                        class="w-full h-11 text-xs px-2 py-1 border border-gray-300 rounded shadow-sm rtransition focus:border-gray-300"
                        tabindex="3"
                    ></textarea>
                </div>
                <div class="flex flex-wrap justify-center">
                    <button
                        @click.prevent="doClose()"
                        type="button"
                        class="text-white bg-primary-600 hover:bg-primary-700 font-medium rounded text-xs px-6 py-1">
                        {{ $t('save') }}
                    </button>
                </div>
            </div>
        </div>
    </div>
</template>

<script lang="ts">
import { ChatBotIcon, SelectIcon } from '@/assets/icons/ai';
import { ecEraser, ecPlus } from "@/assets/icons";
import { AIFields, AIFieldSetting } from '@/store/modules/ai';
import { valueFromPath } from '@/utils/ai-helpers';
import Popover from '@/components/SideBar/AI/Popover.vue';

export default {
    name: "AIDesc",
    components: {
        Popover,
    },
    props: {
        field: {
            type: Object,
            default() {
                return {};
            }
        },
        path: {
            type: String,
            default: ''
        }
    },
    data() {
        return {
            id: `aidesc-${this.$helpers.randid()}`,
            open: false,
            timeout: undefined as ReturnType<typeof setTimeout> | undefined,
            icons: {
                ChatBotIcon,
                ecEraser,
                ecPlus,
                SelectIcon
            },
            value: {
                value: '',
                description: '',
                type: 'string'
            },
            originalValue: {} as AIFieldSetting,
            popoverOpen: false
        }
    },
    computed: {
        editing() {
            return this.$store.getters['builder/editingElement'];
        },

        aiFields() {
            return this.$store.getters['ai/fields'] || {} as AIFields;
        },

        fieldPath() {
            if (!this.field.name) {
                return null;
            }
            return (this.path ? this.path + '.' : '') + this.field.name;
        },

        predefinedRoles() {
            return [
                'Section leading title',
                'Section title',
                'Section sub-title',
                'Section description',
                'Section content',
                'Leading title',
                'Title',
                'Sub-title',
                'Description',
                'Content',
                'Item leading title',
                'Item title',
                'Item sub-title',
                'Item description',
                'Item content',
                'CTA button text',
                'CTA button title',
                'Image background',
                'Image banner'
            ];
        },

        /* fieldPath() {
            const block = this.editing;
            if (!block) {
                return null;
            }
            const settings = block.data?.settings;
            if (!settings) {
                return null;
            }
            const fieldName = this.field?.data?.name;
            if (!fieldName) {
                return null;
            }

            const elPath = [];
            const ancestorPath:string[] = block?.$parent?.path ? block.$parent.path.split('.') : [];

            if ('items' in settings && Array.isArray(settings.items)) {
                const currentItem = block?.data?.settings?.items?.tabOpened || 0;
                elPath.push(`items[${currentItem}]`, fieldName);
                ancestorPath.push('group', 'settings')
            } else {
                elPath.push(fieldName);
                ancestorPath.push('settings');
            }

            return {
                el: elPath.join('.'),
                ancestors: ancestorPath.join('.')
            }
        }, */

        aiValue(): AIFieldSetting {
            if (!this.editing || !this.fieldPath) {
                return {
                    value: '',
                    description: '',
                    type: 'string'
                }
            };
            const aiFields = this.aiFields[this.editing.data.id];
            return aiFields?.[this.fieldPath] || {
                value: '',
                description: '',
                type: 'string'
            };
        }
    },
    watch: {
        aiValue: {
            handler(val) {
                this.value = {...val};
                this.originalValue = {...val};
            },
            deep: true
        }
    },

    created() {
        this.originalValue = {...this.aiValue};
        this.value = {...this.aiValue};
    },

    methods: {
        doOpen() {
            this.open = true;
            clearTimeout(this.timeout);
            this.timeout = setTimeout(() => {
                this.doFocus('description');
                if (!this.value.value) {
                    this.doAddValue();
                }
            }, 50);
        },

        doClose() {
            this.open = false;
            this.doUpdate(this.value);
        },

        setDescription(description: string) {
            const updatedValue = {
                ...this.value,
                description
            };
            this.doUpdate(updatedValue);
        },

        doAddValue() {
            const path = this.fieldPath;
            const block = this.editing;
            if (!path || !block || !block.data?.settings) {
                return;
            }
            const value = valueFromPath(block, `data.settings.${path}`);
            console.log(value);
            if (value && 'string' === typeof value) {
                this.value.value = value;
            }
            // else if(this.field.type === 'picker' && this.field.options?.type === 'image') {
            //     this.value.value = value.value;
            // }

            this.doUpdate(this.value);
        },

        doClear(type: 'description' | 'value') {
            this.value[type] = '';
            this.doFocus(type);
        },

        doFocus(type: 'description' | 'value') {
            const textarea = document.getElementById(`${this.id}-${type}`);
            if (textarea) {
                textarea.focus();
            }
        },

        doUpdate(value: AIFieldSetting) {
            const path = this.fieldPath;
            if (!path) {
                return;
            }
            this.value.value = value.value.trim();
            this.value.description = value.description.trim();
            if(this.field.type === 'picker' && this.field.options?.type === 'image') {
                this.value.type = 'image';
            }
            else
            {
                this.value.type = 'string';
            }

            if (!this.value.description && !this.value.value) {
                this.$store.commit('ai/deleteField', [this.editing.data.id, path]);
            } else {
                this.$store.commit('ai/updateField', {
                    [this.editing.data.id]: {
                        [path]: this.value
                    }
                });
            }
        },

        onCancel() {
            this.doUpdate(this.originalValue)
        },

        onUpdate() {
            this.originalValue = {...this.value};
        }
    },
};
</script>
